-- QA-only additive update; refuse any existing approval history.
begin;
do $$
declare b bigint; v bigint;
begin
 select base_version,version into b,v from public.zukait_vehicle_index_meta where id=true for update;
 if b is distinct from 4 or v is distinct from 4 or exists(select 1 from public.zukait_vehicle_index_audit) or (select count(*) from public.zukait_vehicle_index_entries where kind='ADD_MAKE')<>34 or (select count(*) from public.zukait_vehicle_index_entries where kind='ADD_MODEL')<>337 or exists(select 1 from public.zukait_vehicle_index_entries where kind in ('MAKE_ALIAS','MODEL_ALIAS')) then raise exception 'base_version_or_approval_conflict'; end if;
end $$;
update public.zukait_vehicle_index_meta set base_version=5,version=5 where id=true;
commit;
